import { ProcessHandle } from "../runtime/process";
import { OutputTail } from "../runtime/tail";
import { EventBus } from "../transport/eventBus";
import { Clock } from "../util/clock";
import { ExitWatcher } from "./exitWatcher";
import { LogPump } from "./logPump";

interface Running {
  pump: LogPump;
  watcher: ExitWatcher;
}

/** Owns the per-job pump and exit watcher; driven by the host loop. */
export class Supervisor {
  private readonly running = new Map<string, Running>();

  constructor(
    private readonly bus: EventBus<JobEvent>,
    private readonly clock: Clock,
    private readonly config: ConsoleConfig,
  ) {}

  attach(jobId: string, name: string, proc: ProcessHandle): void {
    if (this.running.has(jobId)) throw new Error(`job ${jobId} already attached`);
    const pump = new LogPump(jobId, new OutputTail(proc), this.bus, this.clock, this.config);
    const watcher = new ExitWatcher(jobId, proc, this.bus, this.clock, () => this.detach(jobId));
    this.running.set(jobId, { pump, watcher });
    this.bus.publish("control", { kind: "started", jobId, name, at: this.clock.now() });
  }

  tick(): void {
    for (const { pump, watcher } of [...this.running.values()]) {
      pump.tick();
      watcher.tick();
    }
  }

  activeJobs(): string[] {
    return [...this.running.keys()];
  }

  private detach(jobId: string): void {
    const r = this.running.get(jobId);
    if (!r) return;
    r.pump.stop();
    this.running.delete(jobId);
  }
}
import { JobEvent } from "../domain/events";
import { JobView, statusForExit } from "../domain/job";
import { JobViewStore } from "../store/jobViewStore";

/** Folds job events into the read model the console API serves. */
export class JobProjection {
  constructor(private readonly store: JobViewStore) {}

  apply(e: JobEvent): void {
    switch (e.kind) {
      case "started":
        this.store.put({
          id: e.jobId,
          name: e.name,
          status: "running",
          exitCode: null,
          log: [],
          seq: 0,
          startedAt: e.at,
          endedAt: null,
        });
        return;
      case "timeline": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        if (e.seq <= view.seq) return; // stale snapshot
        this.store.put({ ...view, status: "running", log: e.lines, seq: e.seq });
        return;
      }
      case "closed": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        this.store.put({ ...view, status: statusForExit(e.exitCode), exitCode: e.exitCode, endedAt: e.at });
        return;
      }
    }
  }

  private blank(id: string): JobView {
    return { id, name: id, status: "running", exitCode: null, log: [], seq: 0, startedAt: 0, endedAt: null };
  }
}
